+	s.mu.Lock()
+	defer s.mu.Unlock()
+	k := memberKey{orgID, userID}
+	m, ok := s.members[k]
+	if !ok {
+		return ErrNotFound
+	}
+	if err := check(m); err != nil {
+		return err
+	}
+	if m.Role == RoleOwner && s.ownersLocked(orgID) == 1 {
+		return ErrLastOwner
+	}
+	delete(s.members, k)
+	return nil
