// isOwnerOrAdmin reports whether a role is one that only an owner may give, change or remove.
func isOwnerOrAdmin(r store.Role) bool { return auth.Admins.Allows(r) }

// updateMember changes a member's role. Nobody changes their own role, and only owners give, or change the role of, an
// owner or an admin.
func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	if target == p.UserID {
		writeError(w, http.StatusForbidden, "forbidden", "nobody may change their own role")
		return
	}
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	m, err := s.store.UpdateMember(p.OrgID, target, func(m *store.Member) error {
		if p.Role != store.RoleOwner && (isOwnerOrAdmin(m.Role) || isOwnerOrAdmin(in.Role)) {
			return refusal("only owners give or change owner and admin roles")
		}
		m.Role = in.Role
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

// removeMember removes a member. Anyone may leave. Otherwise only owners and admins remove members, and only owners remove
// an owner or an admin.
func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	if target != p.UserID && !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
		return
	}
	err := s.store.RemoveMemberChecked(p.OrgID, target, func(m store.Member) error {
		if target != p.UserID && isOwnerOrAdmin(m.Role) && p.Role != store.RoleOwner {
			return refusal("only owners remove owners and admins")
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

